/**
 * Opportunity Score (espelho de src/scoring/opportunity-score.mjs)
 * 30 desconto | 20 comissão | 15 rating | 10 reviews | 10 sales | 10 histórico | 5 cupom
 */
function clamp(n, min, max) { return Math.max(min, Math.min(max, n)); }

function scoreOne(p) {
  const price = Number(p.price);
  const original = p.original_price != null ? Number(p.original_price) : null;
  const avg = p.avg_price_30d != null ? Number(p.avg_price_30d) : null;
  const min30 = p.min_price_30d != null ? Number(p.min_price_30d) : null;
  const max30 = p.max_price_30d != null ? Number(p.max_price_30d) : null;
  const samples = Number(p.samples_30d || 0);

  const announced = (original && original > price) ? ((original - price) / original) * 100 : 0;
  const historical = (avg && avg > price) ? ((avg - price) / avg) * 100 : 0;
  const effective = historical * 0.7 + announced * 0.3;
  const discount = clamp((effective / 50) * 30, 0, 30);

  const flags = [];
  if (min30 != null && price <= min30 && samples >= 3) flags.push('MENOR_PRECO_30D');
  if (historical >= 25) flags.push('ABAIXO_DA_MEDIA_HISTORICA');

  const totalPct = Number(p.commission_percent || 0) + Number(p.extra_commission_percent || 0);
  const commission = clamp((totalPct / 15) * 20, 0, 20);
  const potential_revenue = Math.round(((price * totalPct) / 100) * 100) / 100;

  const rating = p.rating != null ? clamp((Number(p.rating) / 5) * 15, 0, 15) : 0;
  const reviews = p.review_count > 0 ? clamp((Math.log10(Number(p.review_count) + 1) / Math.log10(5001)) * 10, 0, 10) : 0;
  const sales = p.sold_count > 0 ? clamp((Math.log10(Number(p.sold_count) + 1) / Math.log10(10001)) * 10, 0, 10) : 0;

  let price_history = 0;
  if (samples >= 2 && min30 != null && max30 != null) {
    const range = max30 - min30;
    price_history = range <= 0 ? 2 : clamp((1 - (price - min30) / range) * 10, 0, 10);
  }

  const coupon = p.has_active_coupon ? 5 : 0;
  const total = Math.round((discount + commission + rating + reviews + sales + price_history + coupon) * 100) / 100;

  return {
    product_id: p.id,
    opportunity_score: clamp(total, 0, 100),
    breakdown: { discount, commission, rating, reviews, sales, price_history, coupon },
    flags,
    potential_revenue
  };
}

const threshold = Number($env.OPPORTUNITY_SCORE_THRESHOLD || 70);
return $input.all().map((item) => {
  const scored = scoreOne(item.json);
  return {
    json: {
      ...scored,
      pass: scored.opportunity_score >= threshold,
      threshold
    }
  };
});
